import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUpRight, BadgeCheck, BriefcaseBusiness, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardList, CloudUpload, Download, FileText, Heart, LayoutDashboard, LockKeyhole, Menu, Pencil, Plus, QrCode, Search, Settings2, ShieldCheck, Sparkles, UserRound, WalletCards, X } from 'lucide-react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from './integrations/supabase/client';
import CandidateResumePreview, { fillTemplateHtml } from './CandidateResumePreview';
import type { ResumePreviewCandidate, ResumePreviewTemplate } from './CandidateResumePreview';
import AssistantChat from './AssistantChat';
import ResolvedImage from './ResolvedImage';
import { persistImageSource } from './lib/imageSources';
const AdminPanel = lazy(()=>import('./AdminPanel'));

type Tier = 'Básico' | 'Intermediário' | 'Profissional';
type Resume = ResumePreviewCandidate;
type ResumeTemplate = ResumePreviewTemplate & { clean_background_url?:string|null; template_schema?:unknown; creation_type?:string|null };
const tiers: { name: Tier; price: number; desc: string; features: string[]; tone: string; badge?: string }[] = [
  { name: 'Básico', price: 2, desc: 'O essencial para dar o próximo passo.', features: ['1 modelo à sua escolha', 'Currículo em PDF', 'Layout limpo e objetivo'], tone: 'sage' },
  { name: 'Intermediário', price: 3, desc: 'Mais presença para suas conquistas.', features: ['Todos os modelos intermediários', 'Revisão visual aprimorada', 'Destaque para suas habilidades'], tone: 'gold', badge: 'MAIS ESCOLHIDO' },
  { name: 'Profissional', price: 5, desc: 'Uma apresentação à altura do seu talento.', features: ['Coleção profissional completa', 'Design premium e refinado', 'Hierarquia visual estratégica'], tone: 'dark' },
];
const colors = ['#779283','#c5a56c','#394b43','#ab796b','#7b8d9d','#b18b78','#54685b','#ceaa6b'];
const names = ['Essencial','Clareza','Primeiro passo','Horizonte','Trajetória','Foco','Conquista','Raiz','Atitude','Presença','Ponto de partida','Movimento','Vértice','Singular','Aurora','Marco','Caminho','Perspectiva','Legado','Novo capítulo'];
const templates = Object.fromEntries(tiers.map((tier, t) => [tier.name, t>0?[]:names.map((name, i) => ({ id: `${t}-${i}`, name, color: colors[i % colors.length], layout: i % 3 }))]));
const blank: Resume = { name:'', email:'', phone:'', city:'', role:'', summary:'', experience:'', education:'', skills:'', linkedin:'', photoUrl:'', birthDate:'', maritalStatus:'', nationality:'', driverLicense:'', portfolio:'' };
const ACCESS_TOKEN_KEY = 'cv_access_token';
const CANDIDATE_CACHE_KEY = 'cv_candidate_cache';
const CANDIDATE_PHOTO_KEY = 'cv_candidate_photo_cache';
const ADMIN_ORDERS_CACHE_KEY = 'cv_admin_orders_cache';
const PLANS_CACHE_KEY = 'cv_plans_cache';
const TEMPLATES_CACHE_KEY = 'cv_templates_cache';
const tierSlug: Record<Tier,string> = { Básico:'basico', Intermediário:'intermediario', Profissional:'profissional' };
const tierToDbCategory: Record<Tier,'basic'|'intermediate'|'professional'> = { Básico:'basic', Intermediário:'intermediate', Profissional:'professional' };
const dbCategoryToTier: Record<string,Tier> = { basic:'Básico',basico:'Básico','básico':'Básico',intermediate:'Intermediário',intermediario:'Intermediário','intermediário':'Intermediário',professional:'Profissional',profissional:'Profissional' };
type Order = { id:string; client_name:string; client_email:string; client_phone:string; plan:string; payment_status:string; download_released:boolean; amount_cents:number|null; created_at:string; template_id:string|null; payment_proof_path:string|null };
type PixConfig = { id:string; plan_id:string; pix_key:string; recipient_name:string; qr_code_object_path:string|null; is_active:boolean };
type Checkout = { amount_cents:number; recipient_name:string; pix_key:string; qr_code_object_path:string|null; payment_status:string };
function readCache<T>(key:string,fallback:T):T{try{const value=localStorage.getItem(key);return value?JSON.parse(value) as T:fallback}catch{return fallback}}
function cacheTemplateCatalog(catalog:Record<Tier,ResumeTemplate[]>){try{const safeCatalog=Object.fromEntries(Object.entries(catalog).map(([tier,items])=>[tier,items.map(item=>({...item,preview_url:item.preview_url?.startsWith('data:')&&item.preview_url.length>50000?'':item.preview_url}))]));localStorage.setItem(TEMPLATES_CACHE_KEY,JSON.stringify(safeCatalog))}catch{/* cache quota failures do not affect the in-memory catalog */}}
function readTemplateCatalog():Record<Tier,ResumeTemplate[]>{const cached=readCache(TEMPLATES_CACHE_KEY,templates as Record<Tier,ResumeTemplate[]>);const catalog={...cached,Intermediário:(cached.Intermediário||[]).filter(item=>!/^1-\d+$/.test(item.id)),Profissional:(cached.Profissional||[]).filter(item=>!/^2-\d+$/.test(item.id))};cacheTemplateCatalog(catalog);return catalog}

function MiniResume({ color, layout, name, photo }: { color:string; layout:number; name:string; photo?:string }) {
  return <div className={`mini-resume layout-${layout}`}><div className="mini-top" style={{ background: color }}>{photo?<img className="mini-avatar-image" src={photo} alt=""/>:<span className="mini-avatar"/>}<span><b>{name || 'Seu nome aqui'}</b><i>{layout === 1 ? 'Especialista • Profissional' : 'Profissional • Área de atuação'}</i></span></div><div className="mini-body"><div><b>PERFIL</b><i/><i/><i className="short"/><b>EXPERIÊNCIA</b><i/><i/><i className="short"/><b>FORMAÇÃO</b><i/><i className="short"/></div><aside><b>CONTATO</b><i/><i className="short"/><b>COMPETÊNCIAS</b><i/><i/><i/><i className="short"/></aside></div></div>
}
function Brand({ onClick }: { onClick:()=>void }) { return <button className="brand" onClick={onClick}><span className="brand-mark"><FileText size={19}/><span/></span><span>próxima<span className="brand-light">página</span><small>CURRÍCULOS COM PROPÓSITO</small></span></button> }
async function compressPhoto(file:File):Promise<string>{if(!file.type.startsWith('image/'))throw new Error('Escolha um arquivo de imagem.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{const scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{alpha:false});if(!context)throw new Error('Não foi possível processar a imagem.');context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high';context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.92)}finally{bitmap.close()}}
function App() {
  const [admin, setAdmin] = useState(location.pathname === '/admin');
  const [active, setActive] = useState<Tier>('Intermediário');
  const [selected, setSelected] = useState<string | null>(null);
  const [purchasedTemplateId, setPurchasedTemplateId] = useState<string | null>(()=>{try{const token=localStorage.getItem(ACCESS_TOKEN_KEY);if(!token)return null;const draft=JSON.parse(localStorage.getItem('cv_resume_draft_'+token)||'{}');return typeof draft.template_id==='string'?draft.template_id:null}catch{return null}});
  const [previewTemplate, setPreviewTemplate] = useState<ResumeTemplate|null>(null);
  const [candidate, setCandidate] = useState<Resume>(()=>{try{const cached=JSON.parse(localStorage.getItem(CANDIDATE_CACHE_KEY)||'{}') as Resume;const cachedPhoto=localStorage.getItem(CANDIDATE_PHOTO_KEY)||'';return {...blank,...cached,photoUrl:cached.photoUrl||cachedPhoto||''}}catch{return blank}});
  const [templateCatalog, setTemplateCatalog] = useState<Record<Tier,ResumeTemplate[]>>(readTemplateCatalog);
  const [step, setStep] = useState<'form'|'plans'|'payment'|'done'|null>(null);
  const [showForm, setShowForm] = useState(false);
  const [saved, setSaved] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [query, setQuery] = useState('');
  const [toast, setToast] = useState('');
  const [adminTab, setAdminTab] = useState('Visão geral');
  const [approved, setApproved] = useState(false);
  const [prices, setPrices] = useState<Record<Tier,number>>(()=>({...{Básico:2, Intermediário:3, Profissional:5},...readCache(PLANS_CACHE_KEY,{})}));
  const [planIds, setPlanIds] = useState<Record<Tier,string>>(()=>readCache(`${PLANS_CACHE_KEY}_ids`,{Básico:'',Intermediário:'',Profissional:''}));
  const [pixKey, setPixKey] = useState('contato@proximapagina.com.br');
  const [offline, setOffline] = useState(!navigator.onLine);
  const [accessToken, setAccessToken] = useState(()=>localStorage.getItem(ACCESS_TOKEN_KEY) ?? '');
  const [checkout, setCheckout] = useState<Checkout|null>(null);
  const [checkoutLoading, setCheckoutLoading] = useState(false);
  const [uploadingProof, setUploadingProof] = useState(false);
  const [proofSent, setProofSent] = useState(false);
  const [pdfBusy, setPdfBusy] = useState(false);
  const [session, setSession] = useState<Session|null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [adminEmail, setAdminEmail] = useState('');
  const [adminPassword, setAdminPassword] = useState('');
  const [hasAdmin, setHasAdmin] = useState<boolean | null>(null);
  const [checkingAdminExists, setCheckingAdminExists] = useState(true);
  const [settingUpAdmin, setSettingUpAdmin] = useState(false);
  const [orders, setOrders] = useState<Order[]>(()=>{try{return JSON.parse(localStorage.getItem(ADMIN_ORDERS_CACHE_KEY)||'[]')}catch{return []}});
  const [pixConfigs, setPixConfigs] = useState<PixConfig[]>([]);
  const [recipientName, setRecipientName] = useState('');
  const galleryRef = useRef<HTMLDivElement>(null);
  const adminGalleryRef = useRef<HTMLDivElement>(null);
  useEffect(() => { const on=()=>setOffline(navigator.onLine); window.addEventListener('online',on); window.addEventListener('offline',on); return ()=>{window.removeEventListener('online',on);window.removeEventListener('offline',on)}; }, []);
  useEffect(()=>{try{localStorage.setItem(CANDIDATE_CACHE_KEY,JSON.stringify(candidate));if(candidate.photoUrl)localStorage.setItem(CANDIDATE_PHOTO_KEY,candidate.photoUrl);else localStorage.removeItem(CANDIDATE_PHOTO_KEY)}catch{try{localStorage.removeItem(TEMPLATES_CACHE_KEY);localStorage.setItem(CANDIDATE_CACHE_KEY,JSON.stringify(candidate));if(candidate.photoUrl)localStorage.setItem(CANDIDATE_PHOTO_KEY,candidate.photoUrl)}catch{notify('Não foi possível salvar todos os dados neste dispositivo.')}}},[candidate]);
  useEffect(()=>{try{localStorage.setItem(PLANS_CACHE_KEY,JSON.stringify(prices));localStorage.setItem(`${PLANS_CACHE_KEY}_ids`,JSON.stringify(planIds))}catch{/* keep the in-memory plan fallback */}},[prices,planIds]);
  useEffect(()=>{cacheTemplateCatalog(templateCatalog)},[templateCatalog]);
  useEffect(()=>{
    let alive=true;
    const load=async()=>{
      try{
        const {data,error}=await supabase.from('plans').select('id,slug,name,price_cents,is_active').eq('is_active',true).order('sort_order');
        if(!error&&alive&&data?.length){setPlanIds(current=>{const next={...current};for(const plan of data){const tier=tiers.find(item=>tierSlug[item.name]===plan.slug);if(tier)next[tier.name]=plan.id}return next});setPrices(current=>{const next={...current};for(const plan of data){const tier=tiers.find(item=>tierSlug[item.name]===plan.slug);if(tier)next[tier.name]=plan.price_cents/100}return next})}
      }catch{/* local plan prices remain available offline */}
      try{
        const {data,error}=await supabase.from('templates').select('id,name,category,preview_url,generated_html,clean_background_url,template_schema,creation_type,is_active').eq('is_active',true).order('created_at',{ascending:false});
        if(!error&&alive&&data){const next:Record<Tier,ResumeTemplate[]>={'Básico':[],'Intermediário':[],'Profissional':[]};for(const row of data){const tier=dbCategoryToTier[(row.category||'').toLowerCase()];if(tier){const index=next[tier].length;next[tier].push({id:row.id,name:row.name,color:colors[index%colors.length],layout:index%3,preview_url:row.preview_url,generated_html:row.generated_html,clean_background_url:row.clean_background_url,template_schema:row.template_schema,creation_type:row.creation_type})}}for(const plan of tiers){if(!next[plan.name].length)next[plan.name]=templates[plan.name]}setTemplateCatalog(next);cacheTemplateCatalog(next)}
      }catch{/* local template gallery remains available offline */}
    };
    load();
    supabase.auth.getSession().then(({data})=>{if(alive){setSession(data.session);if(!data.session)setAuthLoading(false)}}).catch(()=>{if(alive)setAuthLoading(false)});
    const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{setSession(next);setAuthLoading(Boolean(next))});
    return ()=>{alive=false;subscription.unsubscribe()};
  },[]);
  useEffect(()=>{let alive=true;const check=async()=>{if(!session){setIsAdminUser(false);setAuthLoading(false);return}try{const {data,error}=await supabase.rpc('has_role',{_user_id:session.user.id,_role:'admin'});if(alive){setIsAdminUser(!error&&data===true);setAuthLoading(false)}}catch{if(alive){setIsAdminUser(false);setAuthLoading(false)}}};check();return()=>{alive=false}},[session]);
  useEffect(()=>{if(!accessToken)return;let alive=true;supabase.rpc('get_resume_status',{_token:accessToken}).then(({data})=>{const status=data?.[0];if(alive&&status?.template_id)setPurchasedTemplateId(status.template_id);if(alive&&status?.payment_status==='approved'&&status.download_released){if(status.data&&typeof status.data==='object'&&!Array.isArray(status.data))setCandidate({...blank,...status.data as Resume});setApproved(true);setStep('done')}},()=>{});return()=>{alive=false}},[accessToken]);
  useEffect(()=>{
    if(!admin)return;
    let alive=true;
    setCheckingAdminExists(true);
    supabase.rpc('has_any_admin').then(({data,error})=>{
      if(!alive)return;
      setHasAdmin(!error&&typeof data==='boolean'?data:true); // em caso de erro, postura segura
      setCheckingAdminExists(false);
    },()=>{if(alive){setHasAdmin(true);setCheckingAdminExists(false)}});
    return()=>{alive=false};
  },[admin,isAdminUser]);
  const handleSetupFirstAdmin=async(e:React.FormEvent)=>{
    e.preventDefault();
    if(!session&&adminPassword.length<6){notify('A senha deve ter no mínimo 6 caracteres.');return}
    setSettingUpAdmin(true);
    try{
      // 1. Se ainda não há sessão, cria a conta (ou reaproveita uma já criada) e entra
      if(!session){
        const {data:signUpData,error:signUpError}=await supabase.auth.signUp({email:adminEmail,password:adminPassword,options:{emailRedirectTo:`${window.location.origin}/admin`}});
        if(signUpError&&!/already|registered/i.test(signUpError.message)){notify(signUpError.message||'Erro ao criar conta.');return}
        if(!signUpData?.session){
          const {error:signInError}=await supabase.auth.signInWithPassword({email:adminEmail,password:adminPassword});
          if(signInError){
            if(/confirm/i.test(signInError.message))notify('Conta criada! Confirme o e-mail recebido e depois clique novamente em "Criar e acessar painel".');
            else notify('Não foi possível entrar com esses dados.');
            return;
          }
        }
      }
      // 2. Ativa o papel de administrador (o servidor bloqueia se já existir um)
      const {error:claimError}=await supabase.rpc('claim_first_admin');
      if(claimError){notify('Não foi possível definir como administrador.');setHasAdmin(true);return}
      setHasAdmin(true);
      setIsAdminUser(true);
      notify('Administrador configurado com sucesso!');
    }finally{setSettingUpAdmin(false)}
  };
  useEffect(()=>{setProofSent(Boolean(accessToken&&localStorage.getItem(`cv_payment_proof_sent_${accessToken}`)==='1'))},[accessToken]);
  useEffect(()=>{if(!isAdminUser)return;let alive=true;const load=async()=>{try{const {data,error}=await supabase.from('resumes').select('id,client_name,client_email,client_phone,plan,payment_status,download_released,amount_cents,created_at,template_id,payment_proof_path').order('created_at',{ascending:false}).limit(100);if(error)throw error;if(alive){const rows=(data||[]) as Order[];setOrders(rows);localStorage.setItem(ADMIN_ORDERS_CACHE_KEY,JSON.stringify(rows))}}catch{try{const rows=JSON.parse(localStorage.getItem(ADMIN_ORDERS_CACHE_KEY)||'[]') as Order[];if(alive)setOrders(rows)}catch{/* empty cache */}}try{await supabase.rpc('seed_default_plans');const {data}=await supabase.from('plans').select('id,slug,name,price_cents,is_active').eq('is_active',true);if(alive&&data)setPrices(current=>{const next={...current};for(const plan of data){const tier=tiers.find(item=>tierSlug[item.name]===plan.slug);if(tier)next[tier.name]=plan.price_cents/100}return next});if(alive&&data)setPlanIds(current=>{const next={...current};for(const plan of data){const tier=tiers.find(item=>tierSlug[item.name]===plan.slug);if(tier)next[tier.name]=plan.id}return next})}catch{/* keep cached plan ids */}try{const {data}=await supabase.from('pix_configs').select('*');if(alive&&data){setPixConfigs(data as PixConfig[]);const first=data.find(config=>config.is_active);if(first){setPixKey(first.pix_key);setRecipientName(first.recipient_name)}}}catch{/* Pix remains read-only while unavailable */}};load();const timer=window.setInterval(load,offline?30000:12000);return()=>{alive=false;window.clearInterval(timer)}},[isAdminUser,offline]);
  useEffect(()=>{if(step!=='payment'||!accessToken)return;let alive=true;const poll=async()=>{try{const {data,error}=await supabase.rpc('get_resume_status',{_token:accessToken});if(error)throw error;const status=data?.[0];if(alive&&status?.payment_status==='approved'&&status.download_released){setApproved(true);setStep('done');return}const {data:checkoutData}=await supabase.rpc('get_checkout',{_token:accessToken});const next=checkoutData?.[0] as Checkout|undefined;if(alive&&next)setCheckout(next)}catch{/* continue polling; cached client state stays visible */}};poll();const timer=window.setInterval(poll,5000);return()=>{alive=false;window.clearInterval(timer)}},[step,accessToken]);
  const activeTemplates=templateCatalog[active]||[];
  const previewIndex=previewTemplate?activeTemplates.findIndex(item=>item.id===previewTemplate.id):-1;
  const navigatePreview=(direction:-1|1)=>{if(!activeTemplates.length)return;const current=previewIndex<0?0:previewIndex;const next=activeTemplates[(current+direction+activeTemplates.length)%activeTemplates.length];if(next){setSelected(next.id);setPreviewTemplate(next)}};
  const chosen = useMemo(()=>Object.values(templateCatalog).flat().find(x=>x.id===selected),[selected,templateCatalog]);
  const notify=(msg:string)=>{setToast(msg); window.setTimeout(()=>setToast(''),2600)};
  const updateOrder=(id:string,updates:Partial<Order>)=>setOrders(current=>{const next=current.map(order=>order.id===id?{...order,...updates}:order);localStorage.setItem(ADMIN_ORDERS_CACHE_KEY,JSON.stringify(next));return next});
  const approvePayment=async(order:Order)=>{if(offline)throw new Error('Conecte-se à internet antes de confirmar pagamentos.');const {error}=await supabase.rpc('admin_set_payment',{_resume_id:order.id,_approve:true});if(error)throw error;updateOrder(order.id,{payment_status:'approved'});notify(`Pagamento de ${order.client_name} aprovado. Libere o PDF em seguida.`)};
  const releaseDownload=async(order:Order)=>{if(offline)throw new Error('Conecte-se à internet antes de liberar downloads.');const {error}=await supabase.rpc('admin_release_download',{_resume_id:order.id,_release:true});if(error)throw error;updateOrder(order.id,{download_released:true});notify(`Download de ${order.client_name} liberado.`)};
  const savePixConfig=async(tier:Tier,key:string,recipient:string,qrCodePath?:string|null,price?:number)=>{if(offline)throw new Error('Conecte-se à internet para salvar.');if(!key.trim()&&!qrCodePath)throw new Error('Informe uma chave Pix ou anexe um QR Code.');if(!recipient.trim())throw new Error('Preencha o nome do recebedor.');const priceValue=price??prices[tier];if(!Number.isFinite(priceValue)||priceValue<0)throw new Error('Informe um preço válido.');const current=pixConfigs.find(row=>row.plan_id===planIds[tier]);const storedQr=qrCodePath?await persistImageSource(qrCodePath,'pix'):qrCodePath===null?null:current?.qr_code_object_path||null;const priceCents=Math.round(priceValue*100);const {data:planId,error}=await supabase.rpc('admin_save_plan_and_pix',{_slug:tierSlug[tier],_price_cents:priceCents,_pix_key:key.trim(),_recipient_name:recipient.trim(),_qr_code_object_path:storedQr as string});if(error)throw error;const id=planId as string;setPlanIds(c=>({...c,[tier]:id}));setPrices(c=>({...c,[tier]:priceCents/100}));setPixConfigs(rows=>[...rows.filter(row=>row.plan_id!==id),{id:current?.id||id,plan_id:id,pix_key:key.trim(),recipient_name:recipient.trim(),qr_code_object_path:storedQr,is_active:true} as PixConfig])};
  const handleUploadProof=async(file?:File)=>{if(!file||!accessToken)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){notify('Escolha uma imagem JPEG, PNG ou WebP.');return}setUploadingProof(true);try{const image=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');if(!ctx){image.close();throw new Error('Não foi possível processar o comprovante.')}ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();const proofDataUrl=canvas.toDataURL('image/jpeg',.82);const {error}=await supabase.rpc('set_payment_proof',{_path:proofDataUrl,_token:accessToken});if(error)throw error;localStorage.setItem(`cv_payment_proof_sent_${accessToken}`,'1');setProofSent(true);notify('Comprovante enviado com sucesso! Nosso time irá conferir para liberar seu download.')}catch(error){notify(error instanceof Error?error.message:'Não foi possível enviar o comprovante.')}finally{setUploadingProof(false)}};
  const handleProcessTemplateAi=async(id:string,tier:Tier,imageUrl:string)=>{
    if(offline)throw new Error('Conecte-se à internet para processar o modelo com IA.');
    const isUuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
    if(!isUuid)throw new Error('Apenas modelos salvos no banco de dados podem ser processados por IA.');
    const {data,error}=await supabase.functions.invoke('process-template-html',{body:{template_id:id,image_url:imageUrl}});
    if(error||!data?.generated_html){console.error('Erro na Edge Function process-template-html:',error||data);throw new Error(data?.error||error?.message||'A IA não conseguiu estruturar o HTML deste modelo.');}
    const generatedHtml=data.generated_html as string;
    setTemplateCatalog(current=>{const next={...current};for(const plan of tiers)next[plan.name]=(current[plan.name]||[]).map(item=>item.id===id?{...item,generated_html:generatedHtml}:item);cacheTemplateCatalog(next);return next});
  };
  const handleImportTemplate=async({name,tier,preview_url}:{name:string;tier:Tier;preview_url:string})=>{
    if(offline)throw new Error('Conecte-se à internet para cadastrar novos modelos.');if(!name.trim())throw new Error('O nome do modelo é obrigatório.');if(!preview_url)throw new Error('Envie uma imagem de referência para o modelo.');
    const storedPreview=await persistImageSource(preview_url,'template');
    const {data,error}=await supabase.from('templates').insert({name:name.trim(),category:tierToDbCategory[tier],preview_url:storedPreview,is_active:true}).select('id,name,preview_url,category,generated_html').single();
    if(error){console.error('Erro ao inserir modelo no Supabase:',error);throw error}
    setTemplateCatalog(current=>{const next={...current,[tier]:[{id:data.id,name:data.name,color:colors[Math.floor(Math.random()*colors.length)],layout:0,preview_url:data.preview_url,generated_html:data.generated_html},...(current[tier]||[])]};cacheTemplateCatalog(next);return next});
    void handleProcessTemplateAi(data.id,tier,storedPreview).catch(error=>{console.warn('Processamento de IA em background:',error);notify(error instanceof Error?error.message:'Falha ao processar o novo modelo com IA.')});
  };
  const handleUpdateTemplate=async(id:string,updates:{name:string;tier:Tier;preview_url?:string})=>{
    if(offline)throw new Error('Conecte-se à internet para atualizar modelos.');if(!updates.name.trim())throw new Error('O nome do modelo é obrigatório.');
    const isUuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
    const previousTemplate=Object.values(templateCatalog).flat().find(item=>item.id===id);
    const {data:currentRow}=isUuid?await supabase.from('templates').select('creation_type').eq('id',id).maybeSingle():{data:null};
    const shouldRebuildAi=isUuid&&currentRow?.creation_type!=='manual'&&Boolean(updates.preview_url&&updates.preview_url!==previousTemplate?.preview_url);
    const storedPreview=shouldRebuildAi&&updates.preview_url?await persistImageSource(updates.preview_url,'template'):updates.preview_url;
    if(isUuid){const payload:{name:string;category:string;preview_url?:string;generated_html?:string|null;creation_type?:string|null}={name:updates.name.trim(),category:tierToDbCategory[updates.tier]};if(shouldRebuildAi&&storedPreview){payload.preview_url=storedPreview;payload.generated_html=null;payload.creation_type=null}const {error}=await supabase.from('templates').update(payload).eq('id',id);if(error)throw error}
    setTemplateCatalog(current=>{const previous=Object.values(current).flat().find(item=>item.id===id);const next={...current};for(const plan of tiers)next[plan.name]=(current[plan.name]||[]).filter(item=>item.id!==id);const updated={id,name:updates.name.trim(),color:previous?.color||colors[0],layout:previous?.layout||0,preview_url:storedPreview||previous?.preview_url,generated_html:shouldRebuildAi?null:previous?.generated_html};next[updates.tier]=[updated,...(next[updates.tier]||[])];cacheTemplateCatalog(next);return next});
    if(shouldRebuildAi&&storedPreview){notify('Nova imagem salva! Iniciando reconstrução do HTML com IA…');void handleProcessTemplateAi(id,updates.tier,storedPreview).catch(error=>{notify(error instanceof Error?error.message:'Falha ao processar o novo layout com IA.')})}
  };
  const handleDeleteTemplate=async(id:string,_tier:Tier)=>{if(offline)throw new Error('Conecte-se à internet para excluir modelos.');const isUuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);if(isUuid){const {error}=await supabase.from('templates').update({is_active:false}).eq('id',id);if(error)throw error}setTemplateCatalog(current=>{const next={...current};for(const plan of tiers)next[plan.name]=(current[plan.name]||[]).filter(item=>item.id!==id);cacheTemplateCatalog(next);return next})};
  const goForm=()=>{setPreviewTemplate(null);setShowForm(true);setStep('form'); setTimeout(()=>document.getElementById('builder')?.scrollIntoView({behavior:'smooth',block:'start'}),50)};
  const startPayment=async(tier:Tier,templateIdToBuy=selected)=>{setActive(tier);if(!candidate.name){setShowForm(true);setStep('form');notify('Conte um pouco sobre você antes de seguir para o Pix.');return}const token=accessToken||crypto.randomUUID();localStorage.setItem(ACCESS_TOKEN_KEY,token);setAccessToken(token);setPurchasedTemplateId(templateIdToBuy);setCheckout(null);setCheckoutLoading(true);setShowForm(false);setStep('payment');try{localStorage.setItem('cv_resume_draft_'+token,JSON.stringify({candidate,plan:tierSlug[tier],template_id:templateIdToBuy,updated_at:new Date().toISOString()}))}catch{/* in-memory draft remains available */}document.getElementById('builder')?.scrollIntoView({behavior:'smooth',block:'start'});try{const templateId=templateIdToBuy&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(templateIdToBuy)?templateIdToBuy:null;const {error:saveError}=await supabase.rpc('save_resume',{_client_email:candidate.email,_client_name:candidate.name,_client_phone:candidate.phone,_data:candidate,_plan:tierSlug[tier],_template_id:templateId as unknown as string,_token:token});if(saveError)throw saveError;const {data,error}=await supabase.rpc('get_checkout',{_token:token});if(error)throw error;const result=data?.[0] as Checkout|undefined;if(result)setCheckout(result)}catch(error){console.warn('Checkout indisponível; os dados continuam salvos localmente.',error);notify('Não foi possível conectar ao Pix agora. Seus dados foram preservados neste dispositivo.')}finally{setCheckoutLoading(false)}};
  const doDownload=async()=>{
    if(!accessToken)return;
    setPdfBusy(true);
    try{
      const {data,error}=await supabase.rpc('get_resume_status',{_token:accessToken});
      if(error)throw error;
      const status=data?.[0];
      if(!status?.download_released||status.payment_status!=='approved')throw new Error('O download ainda não foi liberado.');
      const currentCandidate=status.data&&typeof status.data==='object'&&!Array.isArray(status.data)?{...blank,...status.data as Resume}:candidate;
      if(status.data&&typeof status.data==='object'&&!Array.isArray(status.data))setCandidate(currentCandidate);

      const targetTemplateId=status.template_id||purchasedTemplateId||selected;
      let chosenTemplate=Object.values(templateCatalog).flat().find(template=>template.id===targetTemplateId);
      if(!chosenTemplate&&targetTemplateId&&/^[0-9a-f-]{36}$/i.test(targetTemplateId)){
        const {data:templateData}=await supabase.from('templates').select('id,name,category,preview_url,generated_html').eq('id',targetTemplateId).single();
        if(templateData){
          const tier=dbCategoryToTier[(templateData.category||'').toLowerCase()]||active;
          chosenTemplate={id:templateData.id,name:templateData.name,color:colors[0],layout:0,preview_url:templateData.preview_url,generated_html:templateData.generated_html};
          setTemplateCatalog(current=>({...current,[tier]:[chosenTemplate as ResumeTemplate,...(current[tier]||[]).filter(item=>item.id!==targetTemplateId)]}));
        }
      }
      if(status.template_id)setPurchasedTemplateId(status.template_id);
      if(chosenTemplate?.generated_html?.trim()){
        if(targetTemplateId)setPurchasedTemplateId(targetTemplateId);
        await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));
      }
      const element=document.getElementById('resume-print-preview');
      if(!element)throw new Error('Prévia do currículo não encontrada.');
      const images=Array.from(element.querySelectorAll('img'));
      await Promise.all(images.map(img=>img.complete?Promise.resolve():new Promise<void>(resolve=>{img.onload=()=>resolve();img.onerror=()=>resolve()})));
      await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));
      const [{default:html2canvas},{jsPDF}]=await Promise.all([import('html2canvas'),import('jspdf')]);
      const canvas=await html2canvas(element,{scale:2,useCORS:true,backgroundColor:'#ffffff',windowWidth:794});
      const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});
      const pageWidth=210,pageHeight=297;
      const factor=Math.min(pageWidth/canvas.width,(pageHeight-20)/canvas.height);
      const width=canvas.width*factor,height=canvas.height*factor;
      pdf.addImage(canvas.toDataURL('image/jpeg',.95),'JPEG',(pageWidth-width)/2,(pageHeight-height)/2,width,height);
      const safeName=(currentCandidate.name||'Candidato').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/g,'');
      pdf.save(`Curriculo_${safeName||'Candidato'}.pdf`);
    }catch(error){console.error(error);notify(error instanceof Error?error.message:'Não foi possível gerar o PDF agora.')}finally{setPdfBusy(false)}
  };
  const switchAdmin=(value:boolean)=>{setAdmin(value);history.pushState({},'',value?'/admin':'/');window.scrollTo(0,0)};
  window.onpopstate=()=>setAdmin(location.pathname==='/admin');
  const FormFields=()=> <form className="candidate-form" onSubmit={e=>{e.preventDefault();setSaved(true);setStep('plans');setShowForm(false);notify('Seus dados foram salvos neste dispositivo.')}}>
    <div className="form-heading"><div><span className="eyebrow">SEU PERFIL PROFISSIONAL</span><h2>Vamos contar sua história.</h2><p>Preencha o que puder. Você pode completar ou editar tudo depois.</p></div><button type="button" className="icon-button" onClick={()=>setShowForm(false)} aria-label="Fechar"><X size={18}/></button></div>
    <div className="photo-picker"><div className="candidate-avatar">{candidate.photoUrl?<img src={candidate.photoUrl} alt="Prévia da foto do currículo"/>:<UserRound size={26}/>}</div><div><b>Foto para o currículo <small>OPCIONAL</small></b><p>A imagem é redimensionada para até 350 × 350 px e salva em JPEG.</p><label className="button outline photo-select">Escolher foto<input type="file" accept="image/jpeg,image/png,image/webp" onChange={async e=>{const input=e.currentTarget;const file=input.files?.[0];if(!file)return;try{setCandidate({...candidate,photoUrl:await compressPhoto(file)})}catch(error){notify(error instanceof Error?error.message:'Não foi possível processar essa imagem.')}input.value=''}}/></label>{candidate.photoUrl&&<button className="remove-photo" type="button" onClick={()=>{try{localStorage.removeItem(CANDIDATE_PHOTO_KEY)}catch{}setCandidate({...candidate,photoUrl:''})}}>Remover foto</button>}</div></div>
    <div className="form-grid">
      <label>Nome completo <input required placeholder="Ex.: Ana Souza" value={candidate.name} onChange={e=>setCandidate({...candidate,name:e.target.value})}/></label>
      <label>Área ou cargo desejado <input placeholder="Ex.: Analista financeiro" value={candidate.role} onChange={e=>setCandidate({...candidate,role:e.target.value})}/></label>
      <label>E-mail <input required type="email" placeholder="voce@email.com" value={candidate.email} onChange={e=>setCandidate({...candidate,email:e.target.value})}/></label>
      <label>Telefone / WhatsApp <input placeholder="(00) 00000-0000" value={candidate.phone} onChange={e=>setCandidate({...candidate,phone:e.target.value})}/></label>
      <label>Cidade e estado <input placeholder="Fortaleza, CE" value={candidate.city} onChange={e=>setCandidate({...candidate,city:e.target.value})}/></label>
      <label>Data de nascimento <input type="date" value={candidate.birthDate||''} onChange={e=>setCandidate({...candidate,birthDate:e.target.value})}/></label>
      <label>Estado civil <select value={candidate.maritalStatus||''} onChange={e=>setCandidate({...candidate,maritalStatus:e.target.value})}><option value="">Prefiro não informar</option><option>Solteiro(a)</option><option>Casado(a)</option><option>Divorciado(a)</option><option>Viúvo(a)</option><option>União estável</option></select></label>
      <label>Nacionalidade <input placeholder="Brasileira" value={candidate.nationality||''} onChange={e=>setCandidate({...candidate,nationality:e.target.value})}/></label>
      <label>CNH <select value={candidate.driverLicense||''} onChange={e=>setCandidate({...candidate,driverLicense:e.target.value})}><option value="">Não informar</option><option>Não possuo</option><option>A</option><option>B</option><option>AB</option><option>C</option><option>D</option><option>E</option></select></label>
      <label>LinkedIn <input placeholder="linkedin.com/in/seuperfil" value={candidate.linkedin} onChange={e=>setCandidate({...candidate,linkedin:e.target.value})}/></label>
      <label>Portfólio ou site <input placeholder="seusite.com.br" value={candidate.portfolio||''} onChange={e=>setCandidate({...candidate,portfolio:e.target.value})}/></label>
      <label className="wide">Resumo profissional <textarea rows={3} placeholder="Conte brevemente sua trajetória e seus pontos fortes..." value={candidate.summary} onChange={e=>setCandidate({...candidate,summary:e.target.value})}/></label>
      <label className="wide">Experiências profissionais <textarea rows={4} placeholder="Empresa • Cargo • Período\nPrincipais responsabilidades e resultados..." value={candidate.experience} onChange={e=>setCandidate({...candidate,experience:e.target.value})}/></label>
      <label className="wide">Formação e cursos <textarea rows={3} placeholder="Curso • Instituição • Ano de conclusão" value={candidate.education} onChange={e=>setCandidate({...candidate,education:e.target.value})}/></label>
      <label className="wide">Competências e idiomas <input placeholder="Ex.: Excel, atendimento, inglês intermediário" value={candidate.skills} onChange={e=>setCandidate({...candidate,skills:e.target.value})}/></label>
    </div>
    <div className="form-preview"><div><span className="eyebrow">{chosen?`MODELO SELECIONADO · ${chosen.name.toUpperCase()}`:'PRÉVIA DO SEU PERFIL'}</span><b>{candidate.name||'Seu nome aparecerá aqui'}</b><small>{candidate.role||'Área ou cargo desejado'}{candidate.city?` · ${candidate.city}`:''}</small><div className="form-preview-data">{candidate.email&&<span>{candidate.email}</span>}{candidate.phone&&<span>{candidate.phone}</span>}{candidate.summary&&<span>{candidate.summary}</span>}{candidate.experience&&<span>{candidate.experience.split('\n')[0]}</span>}</div>{chosen&&<button type="button" className="preview-inline-link" onClick={()=>setPreviewTemplate(chosen)}>Ver currículo completo <ArrowUpRight size={13}/></button>}</div><div className="form-preview-design"><MiniResume color={chosen?.color||'#779283'} layout={chosen?.layout||0} name={candidate.name} photo={candidate.photoUrl}/><small>{chosen?.name||'Modelo de exemplo'}</small></div></div>
    <div className="form-foot"><span><LockKeyhole size={14}/> Seus dados são salvos neste dispositivo e enviados ao Supabase ao criar o pedido.</span><button className="button primary" type="submit">Salvar e escolher modelo <ArrowRight size={16}/></button></div>
  </form>;
    if(admin && (authLoading || checkingAdminExists)) return <div className="admin-login-shell"><div className="admin-login-card"><span className="eyebrow">ÁREA PROTEGIDA</span><h1>Validando acesso…</h1></div></div>;
    if(admin && hasAdmin===false && !isAdminUser) return <div className="admin-login-shell"><form className="admin-login-card" onSubmit={handleSetupFirstAdmin}><span className="eyebrow">CONFIGURAÇÃO INICIAL</span><h1>Criar primeiro administrador</h1><p>Este sistema ainda não possui um administrador. Crie sua conta mestre agora.</p>{session?<p>Conectado como <b>{session.user.email}</b>.</p>:<><label>E-mail<input type="email" required autoComplete="username" value={adminEmail} onChange={e=>setAdminEmail(e.target.value)}/></label><label>Senha<input type="password" required minLength={6} autoComplete="new-password" value={adminPassword} onChange={e=>setAdminPassword(e.target.value)}/></label></>}<button className="button primary wide-button" type="submit" disabled={settingUpAdmin}>{settingUpAdmin?'Criando…':'Criar e acessar painel'} <ArrowRight size={16}/></button><button type="button" className="back-link" onClick={()=>switchAdmin(false)}>Voltar à página</button></form></div>;
    if(admin && (!session || !isAdminUser)) return <div className="admin-login-shell"><form className="admin-login-card" onSubmit={async e=>{e.preventDefault();const {error}=await supabase.auth.signInWithPassword({email:adminEmail,password:adminPassword});if(error)notify("Não foi possível entrar. Confira seu acesso de administrador.")}}><span className="eyebrow">PAINEL ADMINISTRATIVO</span><h1>Entre para continuar.</h1><p>Acesse com a conta autorizada para administrar pedidos e recebimentos.</p><label>E-mail<input type="email" required autoComplete="username" value={adminEmail} onChange={e=>setAdminEmail(e.target.value)}/></label><label>Senha<input type="password" required autoComplete="current-password" value={adminPassword} onChange={e=>setAdminPassword(e.target.value)}/></label><button className="button primary wide-button" type="submit">Entrar <ArrowRight size={16}/></button><button type="button" className="back-link" onClick={()=>switchAdmin(false)}>Voltar à página</button></form></div>;
    if(admin && isAdminUser) return <Suspense fallback={<div className="admin-login-shell"><div className="admin-login-card"><span className="eyebrow">PAINEL ADMINISTRATIVO</span><h1>Carregando painel…</h1></div></div>}><AdminPanel tab={adminTab} setTab={setAdminTab} tier={active} setTier={setActive} orders={orders} templates={templateCatalog} prices={prices} planIds={planIds} pixConfigs={pixConfigs} offline={offline} onApprove={approvePayment} onRelease={releaseDownload} onSavePix={savePixConfig} onImportTemplate={handleImportTemplate} onUpdateTemplate={handleUpdateTemplate} onDeleteTemplate={handleDeleteTemplate} onProcessTemplateAi={handleProcessTemplateAi} onUpdateTemplateLocal={(saved)=>{setTemplateCatalog(current=>{const next={...current};for(const plan of tiers)next[plan.name]=(current[plan.name]||[]).map(item=>item.id===saved.id?{...item,generated_html:saved.generated_html,clean_background_url:saved.clean_background_url,template_schema:saved.template_schema,creation_type:'manual'}:item);cacheTemplateCatalog(next);return next})}} onSignOut={()=>supabase.auth.signOut()} notify={notify}/></Suspense>;

  return <div className="site-shell"><header className="site-header"><div className="header-inner"><Brand onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}/><nav className={mobileMenu?'nav-open':''}><a href="#como-funciona" onClick={()=>setMobileMenu(false)}>Como funciona</a><a href="#modelos" onClick={()=>setMobileMenu(false)}>Modelos</a><a href="#planos" onClick={()=>setMobileMenu(false)}>Planos</a></nav><div className="header-actions"><button className="admin-link" onClick={()=>switchAdmin(true)}>Área administrativa <ArrowUpRight size={14}/></button><button className="button primary header-cta" onClick={goForm}>Criar meu currículo <ArrowRight size={15}/></button><button className="menu-toggle" onClick={()=>setMobileMenu(!mobileMenu)}><Menu/></button></div></div></header><main><section className="hero"><div className="hero-grid"><div className="hero-copy"><span className="hero-kicker"><span className="kicker-line"/> UMA BOA HISTÓRIA MERECE SER VISTA</span><h1>Seu próximo capítulo começa <em>aqui.</em></h1><p className="hero-sub">Um currículo que mostra o que você sabe fazer — e para onde quer chegar. Escolha o seu, conte sua história e abra novas possibilidades.</p><div className="hero-buttons"><button className="button primary large" onClick={goForm}>Começar meu currículo <ArrowRight size={17}/></button><a className="watch-link" href="#como-funciona"><span><ArrowDown size={15}/></span> Veja como funciona</a></div><div className="hero-trust"><div className="trust-avatars"><i>A</i><i>M</i><i>J</i><i>+</i></div><span><b>Seu talento merece destaque.</b><small>Um primeiro passo simples, do seu jeito.</small></span></div></div><div className="hero-art"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="art-sun"/><div className="hero-plant"><i/><i/><i/><i/><b/></div><div className="floating-note note-top"><span className="note-icon"><Sparkles size={15}/></span><span><b>Feito para você</b><small>Do seu jeito, com seu talento</small></span></div><div className="hero-paper"><div className="paper-top">{candidate.photoUrl?<img className="paper-avatar-image" src={candidate.photoUrl} alt=""/>:<span className="paper-avatar"/>}<span><b>{candidate.name||'Seu nome aqui'}</b><small>{candidate.role||'Seu próximo cargo'}</small></span><span className="paper-star"><Sparkles size={13}/></span></div><div className="paper-rule"/><div className="paper-label">SOBRE MIM</div><i className="paper-line w90"/><i className="paper-line w75"/><i className="paper-line w62"/><div className="paper-label">EXPERIÊNCIA</div><div className="paper-job"><b>Uma trajetória que inspira</b><small>Experiência profissional</small><i className="paper-line w90"/><i className="paper-line w62"/></div><div className="paper-label">HABILIDADES</div><div className="paper-skills"><i/><i/><i/><i/></div><div className="paper-bottom">PRÓXIMA PÁGINA <span>✳</span></div></div><div className="floating-note note-bottom"><span className="note-check"><Check size={16}/></span><span><b>Oportunidades à vista</b><small>Apresente-se com confiança</small></span></div><div className="art-flower flower-a">✳</div><div className="art-flower flower-b">✳</div><span className="art-caption">Cada conquista começa com uma página.</span></div></div><div className="hero-bottom"><span><span className="tiny-star">✳</span> CURRÍCULOS COM IDENTIDADE</span><span className="hero-bottom-right">Um bom começo está mais perto do que você imagina <ArrowDown size={14}/></span></div></section>
    <section className="steps-section" id="como-funciona"><div className="section-intro"><span className="eyebrow">SIMPLES COMO DEVE SER</span><h2>Da sua história à próxima oportunidade.</h2><p>Três passos tranquilos para você se apresentar com confiança.</p></div><div className="step-grid">{[{n:'01',icon:<UserRound/>,t:'Conte sobre você',d:'Compartilhe suas experiências, seus objetivos e tudo que faz você ser você.'},{n:'02',icon:<FileText/>,t:'Escolha seu estilo',d:'Encontre um modelo que combina com a sua trajetória e com o caminho que deseja seguir.'},{n:'03',icon:<ArrowUpRight/>,t:'Dê o próximo passo',d:'Receba seu currículo em PDF, pronto para apresentar ao mundo.'}].map((s,i)=><div className="step-item"><div className="step-top"><span>{s.n}</span><span className="step-icon">{s.icon}</span></div><h3>{s.t}</h3><p>{s.d}</p>{i<2&&<div className="step-connector"/>}</div>)}</div></section>
    <section className="templates-section" id="modelos"><div className="templates-head"><div><span className="eyebrow">UM JEITO PARA CADA HISTÓRIA</span><h2>Encontre o modelo que <em>fala por você.</em></h2><p>Do essencial ao extraordinário, escolha a apresentação que combina com o momento da sua carreira.</p></div><div className="template-count"><b>60</b><span>modelos pensados<br/>para diferentes histórias</span></div></div><div className="template-tabs">{tiers.map(t=><button className={active===t.name?'tab-active':''} onClick={()=>{setActive(t.name);setSelected(null);setPreviewTemplate(null)}}>{t.name}<span>20 opções</span></button>)}</div><div className="template-carousel-wrap"><button className="carousel-arrow" aria-label="Modelos anteriores" onClick={()=>galleryRef.current?.scrollBy({left:-320,behavior:'smooth'})}><ChevronLeft size={17}/></button><div className="template-carousel-track" ref={galleryRef}>{activeTemplates.map((t,i)=><button key={t.id} className={`template-card ${selected===t.id?'chosen':''}`} onClick={()=>{setSelected(t.id);setPreviewTemplate(t)}}><div className="template-preview">{t.preview_url?<ResolvedImage className="template-real-preview" source={t.preview_url} id={t.id} alt={`Modelo ${t.name}`}/>:<MiniResume color={t.color} layout={t.layout} name={candidate.name} photo={candidate.photoUrl}/>}<span className="preview-tag">{active}</span><span className="choose-circle">{selected===t.id?<Check size={14}/>:<Plus size={14}/>}</span></div><div className="template-meta"><span><b>{t.name}</b><small>{['Clássico e direto','Leve e contemporâneo','Elegante e objetivo','Confiante e atual'][i%4]}</small></span><ArrowUpRight size={16}/></div></button>)}</div><button className="carousel-arrow" aria-label="Próximos modelos" onClick={()=>galleryRef.current?.scrollBy({left:320,behavior:'smooth'})}><ChevronRight size={17}/></button></div><div className="templates-foot"><span>✳ Cada modelo recebe suas informações e fica pronto para download em PDF.</span><button className="button outline" onClick={goForm}>Preencher meus dados <ArrowRight size={15}/></button></div></section>
    <section className="plans-section" id="planos"><div className="section-intro"><span className="eyebrow">UM INVESTIMENTO PEQUENO. UM PASSO GRANDE.</span><h2>Escolha o plano que combina <em>com seu momento.</em></h2><p>Sem surpresas. Você escolhe o modelo, confere tudo e paga com Pix.</p></div><div className="plans-grid">{tiers.map((p,i)=><article className={`plan-card plan-${p.tone} ${i===1?'popular':''}`} key={p.name}>{p.badge&&<div className="popular-ribbon"><Sparkles size={12}/>{p.badge}</div>}<div className="plan-number">0{i+1} <span>—</span> CURRÍCULO {p.name.toUpperCase()}</div><div className="plan-name-row"><h3>{p.name}</h3><span className="plan-symbol">{i===0?'✳':i===1?'✦':'✧'}</span></div><p>{p.desc}</p><div className="plan-price"><small>R$</small><strong>{prices[p.name]}</strong><span>,00</span><small className="once">pagamento único</small></div><div className="plan-divider"/><ul>{p.features.map(f=><li><span><Check size={13}/></span>{f}</li>)}</ul><div className="plan-models"><FileText size={15}/><b>20 modelos</b> exclusivos para escolher</div><button className={`button ${i===1?'light-button':'plan-button'} wide-button`} onClick={()=>startPayment(p.name)}>Escolher {p.name}<ArrowRight size={16}/></button><span className="pix-note"><LockKeyhole size={12}/> Pagamento seguro via Pix</span></article>)}</div></section>
    <section className="quote-section"><div className="quote-mark">“</div><blockquote>“A gente não precisa ter um caminho perfeito. Só precisa encontrar uma forma de mostrar com orgulho tudo que já caminhou.”</blockquote><div className="quote-author"><span className="quote-line"/> UM LEMBRETE DA PRÓXIMA PÁGINA</div><div className="quote-flower">✳</div></section>
    <section className="faq-section"><div><span className="eyebrow">AINDA TEM DÚVIDAS?</span><h2>Estamos aqui para<br/><em>deixar tudo claro.</em></h2><p>Seu próximo passo merece começar sem complicação.</p></div><div className="faq-list">{[['Como recebo meu currículo?','Depois de escolher seu plano e modelo, preencha seus dados e pague via Pix. Assim que o pagamento for confirmado, seu PDF fica disponível para baixar.'],['Posso escolher qualquer modelo?','Sim. Cada modalidade tem uma coleção com 20 modelos exclusivos para você escolher.'],['Preciso preencher tudo de uma vez?','Não. Você pode salvar seus dados neste dispositivo e completar o formulário antes de finalizar.'],['Como meus dados são protegidos?','Seus dados são usados para preparar o currículo escolhido. O Lovable conectará o armazenamento protegido e as permissões de acesso.']].map(([q,a],i)=><details open={i===0}><summary>{q}<ChevronDown size={17}/></summary><p>{a}</p></details>)}</div></section>
    <section className="closing-cta"><div className="closing-spark">✳</div><span className="eyebrow">SUA PRÓXIMA PÁGINA ESPERA POR VOCÊ</span><h2>O mundo ainda não conhece<br/>o melhor da sua história.</h2><p>Vamos começar a contar?</p><button className="button light-button large" onClick={goForm}>Criar meu currículo <ArrowRight size={17}/></button><div className="closing-note">Comece agora. Leve seu talento com você.</div></section></main>
    <footer className="site-footer"><div className="footer-top"><Brand onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}/><p>Histórias reais, apresentadas<br/>com cuidado e intenção.</p><button className="footer-admin" onClick={()=>switchAdmin(true)}>Acesso administrativo <ArrowUpRight size={14}/></button></div><div className="footer-bottom"><span>© 2026 Próxima Página. Feito para abrir caminhos.</span><span>Privacidade <i/> Feito com cuidado <span>✳</span></span></div></footer>
    {previewTemplate&&<div className="resume-preview-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)setPreviewTemplate(null)}}><section className="resume-preview-dialog" role="dialog" aria-modal="true" aria-labelledby="resume-preview-title" onKeyDownCapture={event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='p')event.preventDefault()}}><header className="resume-preview-dialog-head"><div><span className="eyebrow">PRÉVIA PRIVADA DO MODELO</span><h2 id="resume-preview-title">{previewTemplate.name}</h2><p>Veja como suas informações ficam neste modelo antes de continuar.</p></div><div className="resume-preview-head-actions"><button type="button" className="preview-nav-button" aria-label="Currículo anterior" title="Currículo anterior" onClick={()=>navigatePreview(-1)} disabled={activeTemplates.length<2}><ChevronLeft size={18}/></button><span className="preview-nav-count" aria-live="polite">{previewIndex>=0?previewIndex+1:1} / {activeTemplates.length}</span><button type="button" className="preview-nav-button" aria-label="Próximo currículo" title="Próximo currículo" onClick={()=>navigatePreview(1)} disabled={activeTemplates.length<2}><ChevronRight size={18}/></button><button className="icon-button" aria-label="Fechar prévia" onClick={()=>setPreviewTemplate(null)}><X size={19}/></button></div></header><div className="resume-preview-scroll"><Suspense fallback={<div className="resume-preview-loading">Carregando prévia do currículo…</div>}><CandidateResumePreview candidate={candidate} template={previewTemplate}/></Suspense></div><footer className="resume-preview-dialog-foot"><span>Esta prévia não oferece download ou impressão.</span><div><button className="button outline" onClick={()=>setPreviewTemplate(null)}>Voltar aos modelos</button><button className="button primary" onClick={goForm}>Preencher meus dados <ArrowRight size={15}/></button><button className="button primary preview-payment-cta" onClick={()=>{setSelected(previewTemplate.id);setPreviewTemplate(null);void startPayment(active,previewTemplate.id)}}>Ir para pagamento <ArrowRight size={15}/></button></div></footer></section></div>}
    {(showForm||step==='payment'||step==='done')&&<div className="builder-overlay" id="builder"><div className="builder-top"><Brand onClick={()=>{setShowForm(false);setStep(null)}}/><button className="icon-button" onClick={()=>{setShowForm(false);setStep(null)}}><X size={19}/></button></div>{showForm?FormFields():step==='payment'?<div className="payment-panel"><button className="back-link" onClick={()=>{setStep('plans');setShowForm(false)}}><ArrowLeft size={15}/> Voltar aos modelos</button><span className="eyebrow">QUASE LÁ</span><h2>Seu próximo passo<br/>já tem forma.</h2><p className="payment-intro">Confira seu pedido e faça o pagamento via Pix. O download será liberado após a aprovação administrativa.</p><div className="payment-summary"><div className="payment-resume">{chosen?.preview_url?<ResolvedImage source={chosen.preview_url} id={chosen.id} className="payment-resume-image" alt="Prévia do modelo" loading="eager"/>:<MiniResume color={chosen?.color||'#779283'} layout={chosen?.layout||0} name={candidate.name} photo={candidate.photoUrl}/>}</div><div><small>SEU PEDIDO</small><h3>{chosen?.name||'Modelo à sua escolha'}</h3><p>{active} · Currículo em PDF</p></div><b>{checkout?`R$ ${(checkout.amount_cents/100).toFixed(2).replace('.',',')}`:'—'}</b></div>{checkoutLoading?<div className="payment-pending"><span className="pulse-dot"/><span><b>Preparando o checkout Pix…</b><small>Consultando o valor e os dados de recebimento do servidor.</small></span></div>:checkout?<><div className="payment-method"><div className="payment-method-head"><span><QrCode size={19}/></span><div><b>Pagamento via Pix</b><small>Escaneie o QR Code ou copie a chave oficial</small></div><span className="secure-label"><LockKeyhole size={12}/> Servidor</span></div>{checkout.qr_code_object_path&&<div className="pix-image-wrap"><ResolvedImage source={checkout.qr_code_object_path} kind="pix" id={`checkout-${chosen?.id||'pix'}`} className="pix-qr-image" alt="QR Code Pix configurado para este plano" loading="eager"/></div>}<div className="pix-placeholder">{!checkout.qr_code_object_path&&<div className="pix-no-qr"><QrCode size={34}/><small>QR Code não cadastrado para este plano</small></div>}<div><small>VALOR DO PEDIDO</small><b>R$ {(checkout.amount_cents/100).toFixed(2).replace('.',',')}</b><span>Recebedor: {checkout.recipient_name||'Não configurado'}</span></div></div>{checkout.pix_key&&<div className="pix-key"><span>{checkout.pix_key}</span><button onClick={async()=>{try{await navigator.clipboard.writeText(checkout.pix_key);notify('Chave Pix copiada.')}catch{notify('Não foi possível copiar a chave Pix.')}}}>Copiar Pix Copia e Cola</button></div>}</div><div className="payment-proof-section"><span className="proof-heading"><FileText size={15}/> <b>Já realizou o Pix?</b></span><p>Envie uma foto ou print do comprovante para agilizar a liberação do seu currículo.</p>{proofSent?<div className="proof-success-badge"><Check size={14}/> Comprovante enviado! Aguardando conferência.</div>:<label className="proof-upload-btn"><CloudUpload size={15}/> {uploadingProof?'Enviando comprovante…':'Anexar comprovante de pagamento'}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploadingProof} onChange={event=>{const input=event.currentTarget;void handleUploadProof(input.files?.[0]);input.value=''}}/></label>}</div><div className="payment-pending"><span className="pulse-dot"/><span><b>{checkout.payment_status==='approved'?'Pagamento aprovado · aguardando liberação':'Aguardando confirmação administrativa'}</b><small>Esta tela consulta o status a cada 5 segundos. O PDF só aparece após aprovação e liberação.</small></span></div><div className="payment-safe"><ShieldCheck size={14}/> Valor e chave Pix vieram da configuração ativa no Supabase.</div></>:<div className="payment-unavailable"><CircleHelp size={21}/><b>Checkout indisponível no momento.</b><span>Seus dados e o token deste pedido permanecem neste dispositivo. Tente novamente quando a conexão com o Supabase estiver disponível.</span><button className="button outline" onClick={()=>startPayment(active)}>Tentar novamente</button></div>}</div>:<div className="payment-panel"><CheckCircle2 size={36}/><h2>Pagamento confirmado!</h2><p>Seu currículo está pronto para seguir com você.</p><button className="button primary" disabled={pdfBusy} onClick={doDownload}>{pdfBusy?<><span className="pdf-spinner"/> Gerando PDF…</>:<><Download size={16}/> Baixar currículo em PDF</>}</button></div>}</div>}
    {!admin&&<AssistantChat candidate={candidate} onUpdateCandidate={setCandidate}/>}
    {(()=>{const pdfTemplateId=purchasedTemplateId||selected;const pdfTemplate=Object.values(templateCatalog).flat().find(item=>item.id===pdfTemplateId);if(pdfTemplate?.generated_html?.trim())return <div id="resume-print-preview" className="print-resume print-resume-custom" dangerouslySetInnerHTML={{__html:fillTemplateHtml(pdfTemplate,candidate)}}/>;return <div id="resume-print-preview" className="print-resume pdf-sheet"><div className="pdf-heading">{candidate.photoUrl&&<img src={candidate.photoUrl} alt=""/>}<div><h1>{candidate.name||'Seu nome'}</h1>{candidate.role&&<h3>{candidate.role}</h3>}</div></div><div className="pdf-contact">{[candidate.email,candidate.phone,candidate.city,candidate.linkedin,candidate.portfolio].filter(Boolean).map((value,index)=><span key={`${value}-${index}`}>{value}</span>)}</div>{candidate.summary&&<section><h2>Resumo profissional</h2><p>{candidate.summary}</p></section>}{candidate.experience&&<section><h2>Experiência profissional</h2><p>{candidate.experience}</p></section>}{candidate.education&&<section><h2>Formação e cursos</h2><p>{candidate.education}</p></section>}{candidate.skills&&<section><h2>Competências e idiomas</h2><p>{candidate.skills}</p></section>}{[candidate.birthDate&&`Nascimento: ${new Date(`${candidate.birthDate}T00:00:00`).toLocaleDateString('pt-BR')}`,candidate.maritalStatus,candidate.nationality,candidate.driverLicense&&candidate.driverLicense!=='Não possuo'?`CNH: ${candidate.driverLicense}`:''].filter(Boolean).length>0&&<section><h2>Informações adicionais</h2><p>{[candidate.birthDate&&`Nascimento: ${new Date(`${candidate.birthDate}T00:00:00`).toLocaleDateString('pt-BR')}`,candidate.maritalStatus,candidate.nationality,candidate.driverLicense&&candidate.driverLicense!=='Não possuo'?`CNH: ${candidate.driverLicense}`:''].filter(Boolean).join(' · ')}</p></section>}</div>})()}<div className="print-control">{approved&&<button onClick={doDownload}><Download/> Baixar meu currículo</button>}</div>{toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}</div>;
}
export default App;
